import urllib.parse, urllib.request, re
queries=['\"lung.cancer.sc.h5ad\"','\"lung.cancer.sc\" \"h5ad\"','\"164616\" \"17277\" lung cancer h5ad','\"164,616\" \"17,277\" \"lung\" \"single\"']
for q in queries:
    print('QUERY',q)
    for engine,urlpat in [('bing','https://www.bing.com/search?q={q}'),('google','https://www.google.com/search?q={q}')]:
        try:
            url=urlpat.format(q=urllib.parse.quote(q))
            req=urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
            html=urllib.request.urlopen(req, timeout=20).read().decode('utf-8','replace')
            print(engine, 'len',len(html))
            # simple snippets
            text=re.sub('<["'^>]+>'"',' ',html)
            for term in ['lung.cancer.sc.h5ad','164616','Patient_006','malignant basal']:
                i=text.lower().find(term.lower())
                if i>=0: print(text[max(0,i-150):i+250])
        except Exception as e: print(engine,'ERR',type(e).__name__,e)
    print()
PY"

